         {"no": "8.7", "ja": "カテゴリ", "vi": "Danh mục", "sel": ".tbl th::カテゴリ", "kind": "label", "trig": "view"},
         {"no": "8.8", "ja": "注文数", "vi": "Số đơn hàng", "sel": ".tbl th::注文数", "kind": "label", "trig": "view", "detail": ["法人の注文の数量の合計（通常の行。アプリ・ESQR の購入数は含めない）。", "Tổng số lượng trong đơn hàng của công ty (dòng thông thường). Không bao gồm số lượng mua qua ứng dụng và ESQR."]},
         {"no": "8.9", "ja": "割合", "vi": "Tỷ lệ", "sel": ".tbl th::割合", "kind": "label", "trig": "view", "detail": ["この月の注文数の合計に対する割合（小数1桁・%）。", "Tỷ lệ so với tổng số đơn hàng của tháng này (1 chữ số thập phân, %)."]},
         {"no": "8.10", "ja": "発注数（本発注・なければ仮発注）", "vi": "Số lượng đặt hàng (đặt hàng chính thức, nếu không có thì đặt hàng tạm)", "sel": ".tbl th::発注数", "kind": "label", "trig": "view", "detail": ["本発注の数。本発注がなければ仮発注の数。", "Số lượng đặt hàng chính thức. Nếu không có đặt hàng chính thức thì lấy số lượng đặt hàng tạm."]},
         {"no": "8.11", "ja": "発注金額（税抜）", "vi": "Số tiền đặt hàng (chưa gồm thuế)", "sel": ".tbl th::発注金額", "kind": "label", "trig": "view", "detail": ["発注数×仕入単価。運営の全役割に見える（運営の中の話。仕入先には出さない）。", "Số lượng đặt hàng × đơn giá nhập. Mọi vai trò vận hành đều thấy (chỉ trong nội bộ vận hành, không hiển thị cho nhà cung cấp)."]},
         {"no": "8.12", "ja": "ランキングの合計", "vi": "Tổng của bảng xếp hạng", "sel": "-", "kind": "label", "trig": "view", "detail": ["注文数・発注数・発注金額の全件の合計。", "Tổng của toàn bộ số đơn hàng, số lượng đặt hàng và số tiền đặt hàng."], "demo_ok": ["コードに合計行がない。台帳 F（2026-10-07 P-LIST の詳細の中の表）に合わせて追加する。", "Code chưa có dòng tổng. Cần thêm theo sổ quyết định F (2026-10-07, bảng trong phần chi tiết của P-LIST)."]},
